const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage();

  await page.goto('https://dev.everruns.com/chat', { waitUntil: 'load', timeout: 60000 });

  // Basic full-page screenshot
  await page.screenshot({ path: 'global-chat.png', fullPage: true });

  // Run axe-core
  const results = await new AxeBuilder({ page }).analyze();

  const fs = require('fs');
  fs.mkdirSync('reports/chat', { recursive: true });
  fs.mkdirSync('reports/chat/screenshots', { recursive: true });
  fs.writeFileSync('reports/chat/axe-results.json', JSON.stringify(results, null, 2));
  fs.copyFileSync('global-chat.png', 'reports/chat/screenshots/global-chat.png');

  await browser.close();
})();

