const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');
const fs = require('fs');

(async () => {
  const url = 'https://dev.everruns.com/chat';
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const context = await browser.newContext();
  const page = await context.newPage();

  // Attempt 3: fix axe navigation race
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await page.waitForLoadState('networkidle').catch(() => {});
  await page.waitForTimeout(5000);
  await page.evaluate(() => { window.stop(); });

  const finalUrl = page.url();

  fs.mkdirSync('reports/chat/screenshots', { recursive: true });
  await page.screenshot({ path: 'reports/chat/screenshots/global-chat-attempt3.png', fullPage: true });

  let results;
  try {
    results = await new AxeBuilder({ page }).analyze();
  } catch (e) {
    // Attempt 4: run axe on whatever URL we ended up on after a fresh goto
    console.error('Attempt 3 failed:', e.message);
    await page.goto(finalUrl, { waitUntil: 'domcontentloaded', timeout: 90000 });
    await page.waitForLoadState('networkidle').catch(() => {});
    await page.waitForTimeout(5000);
    await page.evaluate(() => { window.stop(); });

    await page.screenshot({ path: 'reports/chat/screenshots/global-chat-attempt4.png', fullPage: true });

    try {
      results = await new AxeBuilder({ page }).analyze();
    } catch (e2) {
      console.error('Attempt 4 failed:', e2.message);

      // Attempt 5: inject axe-core from CDN directly
      await page.addScriptTag({ url: 'https://cdn.jsdelivr.net/npm/axe-core/axe.min.js' });
      await page.waitForTimeout(2000);
      const raw = await page.evaluate(async () => await window.axe.run());
      results = raw;
      await page.screenshot({ path: 'reports/chat/screenshots/global-chat-attempt5.png', fullPage: true });
    }
  }

  fs.mkdirSync('reports/chat', { recursive: true });
  fs.writeFileSync('reports/chat/axe-results.json', JSON.stringify({ url: finalUrl, results }, null, 2));

  await browser.close();
})();
